103|                     jv_number_value(b));
104|    jv_free(a);
105|    jv_free(b);
106|    return r;
107|  } else if (jv_get_kind(a) == JV_KIND_STRING && jv_get_kind(b) == JV_KIND_STRING) {
108|    return jv_string_concat(a, b);
