327|jv binop_multiply(jv a, jv b) {
328|  jv_kind ak = jv_get_kind(a);
329|  jv_kind bk = jv_get_kind(b);
330|  if (ak == JV_KIND_NUMBER && bk == JV_KIND_NUMBER) {
331|    jv r = jv_number(jv_number_value(a) * jv_number_value(b));
332|    jv_free(a);
333|    jv_free(b);
334|    return r;
335|  } else if ((ak == JV_KIND_STRING && bk == JV_KIND_NUMBER) ||
336|             (ak == JV_KIND_NUMBER && bk == JV_KIND_STRING)) {
337|    jv str = a;
338|    jv num = b;
339|    if (ak == JV_KIND_NUMBER) {
340|      str = b;
341|      num = a;
342|    }
343|    jv res;
344|    double d = jv_number_value(num);
345|    if (d < 0 || isnan(d)) {
346|      res = jv_null();
347|    } else {
348|      int n = d;
349|      size_t alen = jv_string_length_bytes(jv_copy(str));
350|      res = jv_string_empty(alen * n);
