381|jv binop_mod(jv a, jv b) {
382|  if (jv_get_kind(a) == JV_KIND_NUMBER && jv_get_kind(b) == JV_KIND_NUMBER) {
383|    double na = jv_number_value(a);
384|    double nb = jv_number_value(b);
385|    if (isnan(na) || isnan(nb)) {
386|      jv_free(a);
387|      jv_free(b);
388|      return jv_number(NAN);
389|    }
390|    intmax_t bi = dtoi(nb);
391|    if (bi == 0)
392|      return type_error2(a, b, "cannot be divided (remainder) because the divisor is zero");
393|    // Check if the divisor is -1 to avoid overflow when the dividend is INTMAX_MIN.
394|    jv r = jv_number(bi == -1 ? 0 : dtoi(na) % bi);
395|    jv_free(a);
396|    jv_free(b);
397|    return r;
398|  } else {
399|    return type_error2(a, b, "cannot be divided (remainder)");
400|  }
