542|static jv escape_string(jv input, const char* escapings) {
543|
544|  assert(jv_get_kind(input) == JV_KIND_STRING);
545|  const char* lookup[128] = {0};
546|  const char* p = escapings;
547|  lookup[0] = "\\0";
548|  while (*p) {
549|    lookup[(int)*p] = p+1;
550|    p++;
551|    p += strlen(p);
552|    p++;
553|  }
554|
555|  jv ret = jv_string("");
556|  const char* i = jv_string_value(input);
557|  const char* end = i + jv_string_length_bytes(jv_copy(input));
558|  const char* cstart;
559|  int c = 0;
560|  while ((i = jvp_utf8_next((cstart = i), end, &c))) {
561|    if (c < 128 && lookup[c]) {
562|      ret = jv_string_append_str(ret, lookup[c]);
563|    } else {
564|      ret = jv_string_append_buf(ret, cstart, i - cstart);
565|    }
566|  }
567|  jv_free(input);
568|  return ret;
