1110|static jv minmax_by(jv values, jv keys, int is_min) {
1111|  if (jv_get_kind(values) != JV_KIND_ARRAY)
1112|    return type_error2(values, keys, "cannot be iterated over");
1113|  if (jv_get_kind(keys) != JV_KIND_ARRAY)
1114|    return type_error2(values, keys, "cannot be iterated over");
