1439|/*
1440| * mktime() has side-effects and anyways, returns time in the local
1441| * timezone, not UTC.  We want timegm(), which isn't standard.
1442| *
1443| * To make things worse, mktime() tells you what the timezone
1444| * adjustment is, but you have to #define _BSD_SOURCE to get this
1445| * field of struct tm on some systems.
1446| *
1447| * This is all to blame on POSIX, of course.
1448| *
1449| * Our wrapper tries to use timegm() if available, or mktime() and
1450| * correct for its side-effects if possible.
1451| *
1452| * Returns (time_t)-2 if mktime()'s side-effects cannot be corrected.
1453| */
1454|static time_t my_mktime(struct tm *tm) {
1455|#ifdef HAVE_TIMEGM
1456|  return timegm(tm);
1457|#elif HAVE_TM_TM_GMT_OFF
1458|
1459|  time_t t = mktime(tm);
1460|  if (t == (time_t)-1)
1461|    return t;
1462|  return t + tm->tm_gmtoff;
1463|#elif HAVE_TM___TM_GMT_OFF
1464|  time_t t = mktime(tm);
1465|  if (t == (time_t)-1)
1466|    return t;
1467|  return t + tm->__tm_gmtoff;
1468|#elif WIN32
1469|  return _mkgmtime(tm);
1470|#else
1471|  char *tz;
1472|
1473|  tz = (tz = getenv("TZ")) != NULL ? strdup(tz) : NULL;
1474|  if (tz != NULL)
1475|    setenv("TZ", "", 1);
1476|  time_t t = mktime(tm);
1477|  if (tz != NULL)
1478|    setenv("TZ", tz, 1);
1479|  return t;
