1597|static int jv2tm(jv a, struct tm *tm) {
1598|  memset(tm, 0, sizeof(*tm));
1599|  static const size_t offsets[] = {
1600|    offsetof(struct tm, tm_year),
1601|    offsetof(struct tm, tm_mon),
1602|    offsetof(struct tm, tm_mday),
1603|    offsetof(struct tm, tm_hour),
1604|    offsetof(struct tm, tm_min),
1605|    offsetof(struct tm, tm_sec),
1606|    offsetof(struct tm, tm_wday),
1607|    offsetof(struct tm, tm_yday),
1608|  };
1609|
1610|  for (size_t i = 0; i < (sizeof offsets / sizeof *offsets); ++i) {
1611|    jv n = jv_array_get(jv_copy(a), i);
1612|    if (!jv_is_valid(n))
1613|      break;
1614|    if (jv_get_kind(n) != JV_KIND_NUMBER || jvp_number_is_nan(n)) {
1615|      jv_free(a);
1616|      jv_free(n);
1617|      return 0;
1618|    }
1619|    double d = jv_number_value(n);
1620|    if (i == 0) /* year */
1621|      d -= 1900;
1622|    *(int *)((void *)tm + offsets[i]) = d < INT_MIN ? INT_MIN :
1623|                                        d > INT_MAX ? INT_MAX : (int)d;
1624|    jv_free(n);
1625|  }
1626|
1627|  // We use UTC everywhere (gettimeofday, gmtime) and UTC does not do DST.
1628|  // Setting tm_isdst to 0 is done by the memset.
1629|  // tm->tm_isdst = 0;
1630|
1631|  // The standard permits the tm structure to contain additional members. We
1632|  // hope it is okay to initialize them to zero, because the standard does not
1633|  // provide an alternative.
1634|
1635|  jv_free(a);
1636|  return 1;
1637|}
