12|/*
13|  The intermediate representation for jq filters is as a sequence of
14|  struct inst, which form a doubly-linked list via the next and prev
15|  pointers.
16|
17|  A "block" represents a sequence of "struct inst", which may be
18|  empty.
19|
20|  Blocks are generated by the parser bottom-up, so may have free
21|  variables (refer to things not defined). See inst.bound_by and
22|  inst.symbol.
23| */
24|struct inst {
25|  struct inst* next;
26|  struct inst* prev;
27|
28|  opcode op;
29|
30|  struct {
31|    uint16_t intval;
32|    struct inst* target;
33|    jv constant;
34|    const struct cfunction* cfunc;
35|  } imm;
36|
37|  struct locfile* locfile;
38|  location source;
39|
40|  // Binding
41|  // An instruction requiring binding (for parameters/variables/functions)
42|  // is in one of three states:
43|  //   inst->bound_by = NULL  - Unbound free variable
44|  //   inst->bound_by = inst  - This instruction binds a variable
45|  //   inst->bound_by = other - Uses variable bound by other instruction
46|  // Unbound instructions (references to other things that may or may not
47|  // exist) are created by "gen_foo_unbound", and bindings are created by
48|  // block_bind(definition, body), which binds all instructions in
49|  // body which are unbound and refer to "definition" by name.
50|  struct inst* bound_by;
51|  char* symbol;
52|  int any_unbound;
53|  int referenced;
54|
55|  int nformals;
56|  int nactuals;
57|
58|  block subfn;   // used by CLOSURE_CREATE (body of function)
59|  block arglist; // used by CLOSURE_CREATE (formals) and CALL_JQ (arguments)
60|
61|  // This instruction is compiled as part of which function?
62|  // (only used during block_compile)
63|  struct bytecode* compiled;
64|
65|  int bytecode_pos; // position just after this insn
66|};
