68|static inst* inst_new(opcode op) {
69|  inst* i = jv_mem_alloc(sizeof(inst));
70|  i->next = i->prev = 0;
71|  i->op = op;
72|  i->bytecode_pos = -1;
73|  i->bound_by = 0;
74|  i->symbol = 0;
75|  i->any_unbound = 0;
76|  i->referenced = 0;
77|  i->nformals = -1;
78|  i->nactuals = -1;
79|  i->subfn = gen_noop();
80|  i->arglist = gen_noop();
81|  i->source = UNKNOWN_LOCATION;
82|  i->locfile = 0;
83|  return i;
84|}
