86|static void inst_free(struct inst* i) {
87|  jv_mem_free(i->symbol);
88|  block_free(i->subfn);
89|  block_free(i->arglist);
90|  if (i->locfile)
91|    locfile_free(i->locfile);
92|  if (opcode_describe(i->op)->flags & OP_HAS_CONSTANT) {
