307|static int block_bind_subblock_inner(int* any_unbound, block binder, block body, int bindflags, int break_distance) {
308|  assert(block_is_single(binder));
309|  assert((opcode_describe(binder.first->op)->flags & bindflags) == (bindflags & ~OP_BIND_WILDCARD));
310|  assert(binder.first->symbol);
311|  assert(binder.first->bound_by == 0 || binder.first->bound_by == binder.first);
312|  assert(break_distance >= 0);
313|
314|  binder.first->bound_by = binder.first;
315|  int nrefs = 0;
316|  for (inst* i = body.first; i; i = i->next) {
317|    if (i->any_unbound == 0)
318|      continue;
319|
320|    int flags = opcode_describe(i->op)->flags;
321|    if ((flags & bindflags) == (bindflags & ~OP_BIND_WILDCARD) && i->bound_by == 0 &&
322|        (!strcmp(i->symbol, binder.first->symbol) ||
323|         // Check for break/break2/break3; see parser.y
324|         ((bindflags & OP_BIND_WILDCARD) && i->symbol[0] == '*' &&
325|          break_distance <= 3 && (i->symbol[1] == '1' + break_distance) &&
326|          i->symbol[2] == '\0'))) {
327|      // bind this instruction
328|      if (i->nactuals == -1 || i->nactuals == binder.first->nformals) {
329|        i->bound_by = binder.first;
330|        nrefs++;
331|      }
332|    } else if ((flags & bindflags) == (bindflags & ~OP_BIND_WILDCARD) && i->bound_by != 0 &&
333|               !strncmp(binder.first->symbol, "*anonlabel", sizeof("*anonlabel") - 1) &&
334|               !strncmp(i->symbol, "*anonlabel", sizeof("*anonlabel") - 1)) {
335|      // Increment the break distance required for this binder to match
336|      // a break whenever we come across a STOREV of *anonlabel...
337|      break_distance++;
338|    }
339|
340|    i->any_unbound = (i->symbol && !i->bound_by);
341|
342|    // binding recurses into closures
343|    nrefs += block_bind_subblock_inner(&i->any_unbound, binder, i->subfn, bindflags, break_distance);
344|    // binding recurses into argument list
345|    nrefs += block_bind_subblock_inner(&i->any_unbound, binder, i->arglist, bindflags, break_distance);
346|
347|    if (i->any_unbound)
348|      *any_unbound = 1;
349|  }
350|  return nrefs;
351|}
352|
353|static int block_bind_subblock(block binder, block body, int bindflags, int break_distance) {
354|  int any_unbound;
355|  return block_bind_subblock_inner(&any_unbound, binder, body, bindflags, break_distance);
356|}
