405|static inst* block_take_last(block* b) {
406|  inst* i = b->last;
407|  if (i == 0)
408|    return 0;
409|  if (i->prev) {
410|    i->prev->next = i->next;
411|    b->last = i->prev;
412|    i->prev = 0;
413|  } else {
414|    b->first = 0;
415|    b->last = 0;
416|  }
417|  return i;
