452|static void block_mark_referenced(block body) {
453|  int saw_top = 0;
454|  for (inst* i = body.last; i; i = i->prev) {
455|    if (saw_top && i->bound_by == i && !i->referenced)
456|      continue;
457|    if (i->op == TOP) {
458|      saw_top = 1;
459|    }
460|    if (i->bound_by) {
461|      i->bound_by->referenced = 1;
462|    }
463|
464|    block_mark_referenced(i->arglist);
465|    block_mark_referenced(i->subfn);
466|  }
467|}
