469|block block_drop_unreferenced(block body) {
470|  block_mark_referenced(body);
471|
472|  block refd = gen_noop();
473|  inst* curr;
474|  while ((curr = block_take(&body))) {
475|    if (curr->bound_by == curr && !curr->referenced) {
476|      inst_free(curr);
477|    } else {
478|      refd = BLOCK(refd, inst_block(curr));
479|    }
480|  }
481|  return refd;
