484|jv block_take_imports(block* body) {
485|  jv imports = jv_array();
486|
487|  /* Parser should never generate TOP before imports */
488|  assert(!(body->first && body->first->op == TOP && body->first->next &&
489|        (body->first->next->op == MODULEMETA || body->first->next->op == DEPS)));
490|
491|  while (body->first && (body->first->op == MODULEMETA || body->first->op == DEPS)) {
492|    inst* dep = block_take(body);
493|    if (dep->op == DEPS) {
494|      imports = jv_array_append(imports, jv_copy(dep->imm.constant));
495|    }
496|    inst_free(dep);
497|  }
498|  return imports;
