610|block gen_const_object(block expr) {
611|  int is_const = 1;
612|  jv o = jv_object();
613|  jv k = jv_null();
614|  jv v = jv_null();
615|  for (inst *i = expr.first; i; i = i->next) {
616|    if (i->op == PUSHK_UNDER) {
617|      k = jv_copy(i->imm.constant);
618|      i = i->next;
619|    } else if (i->op != SUBEXP_BEGIN ||
620|        i->next == NULL ||
621|        i->next->op != LOADK ||
622|        i->next->next == NULL ||
623|        i->next->next->op != SUBEXP_END) {
624|      is_const = 0;
625|      break;
626|    } else {
627|      k = jv_copy(i->next->imm.constant);
628|      i = i->next->next->next;
629|    }
630|    if (i != NULL && i->op == PUSHK_UNDER) {
631|      v = jv_copy(i->imm.constant);
632|      i = i->next;
633|    } else if (i == NULL ||
634|        i->op != SUBEXP_BEGIN ||
635|        i->next == NULL ||
636|        i->next->op != LOADK ||
637|        i->next->next == NULL ||
638|        i->next->next->op != SUBEXP_END) {
639|      is_const = 0;
640|      break;
641|    } else {
642|      v = jv_copy(i->next->imm.constant);
643|      i = i->next->next->next;
644|    }
645|    if (i == NULL || i->op != INSERT) {
646|      is_const = 0;
647|      break;
648|    }
649|    if (jv_get_kind(k) != JV_KIND_STRING) {
650|      is_const = 0;
651|      break;
652|    }
653|    o = jv_object_set(o, k, v);
654|    k = jv_null();
655|    v = jv_null();
656|  }
657|  if (!is_const) {
658|    jv_free(o);
659|    jv_free(k);
660|    jv_free(v);
661|    block b = {0,0};
662|    return b;
663|  }
664|  block_free(expr);
665|  return gen_const(o);
666|}
