668|static block gen_const_array(block expr) {
669|  /*
670|   * An expr of all constant elements looks like this:
671|   *
672|   * 0009 FORK 0027
673|   * 0011 FORK 0023
674|   * 0013 FORK 0019
675|   * 0015 LOADK 1
676|   * 0017 JUMP 0021
677|   * 0019 LOADK 2
678|   * 0021 JUMP 0025
679|   * 0023 LOADK 3
680|   * 0025 JUMP 0029
681|   * 0027 LOADK 4
682|   *
683|   * That's: N-1 commas for N elements, N LOADKs, and a JUMP between
684|   * every LOADK.  The sequence ends in a LOADK.  Any deviation and it's
685|   * not a list of constants.
686|   *
687|   * Here we check for this pattern almost exactly.  We don't check that
688|   * the targets of the FORK and JUMP instructions are in the right
689|   * sequence.
690|   */
691|  int all_const = 1;
692|  int commas = 0;
693|  int normal = 1;
694|  jv a = jv_array();
695|  for (inst *i = expr.first; i; i = i->next) {
696|    if (i->op == FORK) {
697|      commas++;
698|      if (i->imm.target == NULL || i->imm.target->op != JUMP ||
699|          jv_array_length(jv_copy(a)) > 0) {
700|        normal = 0;
701|        break;
702|      }
703|    } else if (all_const && i->op == LOADK) {
704|      if (i->next != NULL && i->next->op != JUMP) {
705|        normal = 0;
706|        break;
707|      }
708|      a = jv_array_append(a, jv_copy(i->imm.constant));
709|    } else if (i->op != JUMP || i->imm.target == NULL ||
710|               i->imm.target->op != LOADK) {
711|      all_const = 0;
712|    }
713|  }
714|
715|  if (all_const && normal &&
716|      (expr.last == NULL || expr.last->op == LOADK) &&
717|      jv_array_length(jv_copy(a)) == commas + 1) {
718|    block_free(expr);
719|    return gen_const(a);
720|  }
721|
722|  jv_free(a);
723|  block b = {0,0};
724|  return b;
725|}
