757|// Extract destructuring var names from the block
758|// *vars should be a jv_object (for set semantics)
759|static void block_get_unbound_vars(block b, jv *vars) {
760|  assert(vars != NULL);
761|  assert(jv_get_kind(*vars) == JV_KIND_OBJECT);
762|  for (inst* i = b.first; i; i = i->next) {
763|    if (i->subfn.first) {
764|      block_get_unbound_vars(i->subfn, vars);
765|      continue;
766|    }
767|    if ((i->op == STOREV || i->op == STOREVN) && i->bound_by == NULL) {
