773|/* Build wrappers around destructuring matchers so that we can chain them
774| * when we have errors.  The approach is as follows:
775| * DESTRUCTURE_ALT NEXT_MATCHER (unless last matcher)
776| * existing_matcher_block
777| * JUMP BODY
778| */
779|static block bind_alternation_matchers(block matchers, block body) {
780|  block preamble = {0};
781|  block altmatchers = {0};
782|  block mb = {0};
783|  block final_matcher = matchers;
784|
785|  // Pass through the matchers to find all destructured names.
786|  while (final_matcher.first && final_matcher.first->op == DESTRUCTURE_ALT) {
787|    block_append(&altmatchers, inst_block(block_take(&final_matcher)));
788|  }
789|
790|  // We don't have any alternations here, so we can use the simplest case.
791|  if (altmatchers.first == NULL) {
792|    return bind_matcher(final_matcher, body);
793|  }
794|
795|  // Collect var names
796|  jv all_vars = jv_object();
797|  block_get_unbound_vars(altmatchers, &all_vars);
798|  block_get_unbound_vars(final_matcher, &all_vars);
799|
800|  // We need a preamble of STOREVs to which to bind the matchers and the body.
801|  jv_object_keys_foreach(all_vars, key) {
802|    preamble = BLOCK(preamble,
803|                     gen_op_simple(DUP),
804|                     gen_const(jv_null()),
805|                     gen_op_unbound(STOREV, jv_string_value(key)));
806|    jv_free(key);
807|  }
808|  jv_free(all_vars);
809|
810|  // Now we build each matcher in turn
811|  for (inst *i = altmatchers.first; i; i = i->next) {
812|    block submatcher = i->subfn;
813|
814|    // If we're successful, jump to the end of the matchers
815|    submatcher = BLOCK(submatcher, gen_op_target(JUMP, final_matcher));
816|
817|    // DESTRUCTURE_ALT to the end of this submatcher so we can skip to the next one on error
818|    mb = BLOCK(mb, gen_op_target(DESTRUCTURE_ALT, submatcher), submatcher);
819|
820|    // We're done with this inst and we don't want it anymore
821|    // But we can't let it free the submatcher block.
822|    i->subfn.first = i->subfn.last = NULL;
823|  }
824|  // We're done with these insts now.
825|  block_free(altmatchers);
826|
827|  return bind_matcher(preamble, BLOCK(mb, final_matcher, body));
828|}
