847|block gen_foreach(block source, block matcher, block init, block update, block extract) {
848|  block output = gen_op_targetlater(JUMP);
849|  block state_var = gen_op_var_fresh(STOREV, "foreach");
850|  block loop = BLOCK(gen_op_simple(DUPN),
851|                     // get a value from the source expression:
852|                     source,
853|                     // destructure the value into variable(s) for all the code
854|                     // in the body to see
855|                     bind_alternation_matchers(matcher,
856|                                  // load the loop state variable
857|                                  BLOCK(gen_op_bound(LOADV, state_var),
858|                                        // generate updated state
859|                                        update,
860|                                        // save the updated state for value extraction
861|                                        gen_op_simple(DUP),
862|                                        // save new state
863|                                        gen_op_bound(STOREV, state_var),
864|                                        // extract an output...
865|                                        extract,
866|                                        // ...and output it by jumping
867|                                        // past the BACKTRACK that comes
868|                                        // right after the loop body,
869|                                        // which in turn is there
870|                                        // because...
871|                                        //
872|                                        // (Incidentally, extract can also
873|                                        // backtrack, e.g., if it calls
874|                                        // empty, in which case we don't
875|                                        // get here.)
876|                                        output)));
877|  block foreach = BLOCK(gen_op_simple(DUP),
878|                        init,
879|                        state_var,
880|                        gen_op_target(FORK, loop),
881|                        loop,
882|                        // ...at this point `foreach`'s original input
883|                        // will be on top of the stack, and we don't
884|                        // want to output it, so we backtrack.
885|                        gen_op_simple(BACKTRACK));
886|  inst_set_target(output, foreach); // make that JUMP go bast the BACKTRACK at the end of the loop
887|  return foreach;
