1034|block gen_try(block exp, block handler) {
1035|  /*
1036|   * Produce:
1037|   *
1038|   *  TRY_BEGIN handler
1039|   *  <exp>
1040|   *  TRY_END
1041|   *  JUMP past_handler
1042|   *  handler: <handler>
1043|   *  past_handler:
1044|   *
1045|   * If <exp> backtracks then TRY_BEGIN will backtrack.
1046|   *
1047|   * If <exp> produces a value then we'll execute whatever bytecode follows
1048|   * this sequence.  If that code raises an exception, then TRY_END will wrap
1049|   * and re-raise that exception, and TRY_BEGIN will unwrap and re-raise the
1050|   * exception (see jq_next()).
1051|   *
1052|   * If <exp> raises then the TRY_BEGIN will see a non-wrapped exception and
1053|   * will jump to the handler (note the TRY_END will not execute in this case),
1054|   * and if the handler produces any values, then we'll execute whatever
1055|   * bytecode follows this sequence.  Note that TRY_END will not execute in
1056|   * this case, so if the handler raises an exception, or code past the handler
1057|   * raises an exception, then that exception won't be wrapped and re-raised,
1058|   * and the TRY_BEGIN will not catch it because it does not stack_save() when
1059|   * it branches to the handler.
1060|   */
1061|
1062|  if (block_is_noop(handler))
1063|    handler = BLOCK(gen_op_simple(DUP), gen_op_simple(POP));
1064|
1065|  block jump = gen_op_target(JUMP, handler);
1066|  return BLOCK(gen_op_target(TRY_BEGIN, jump), exp, gen_op_simple(TRY_END),
1067|               jump, handler);
1068|}
