1127|{
1128|  if (jv_is_valid(env))
1129|    return jv_copy(env);
1130|  jv r = jv_object();
1131|  if (environ == NULL)
1132|    return r;
1133|  for (size_t i = 0; environ[i] != NULL; i++) {
1134|    const char *eq;
1135|
1136|    if ((eq = strchr(environ[i], '=')) == NULL)
1137|      r = jv_object_delete(r, jv_string(environ[i]));
1138|    else
1139|      r = jv_object_set(r, jv_string_sized(environ[i], eq - environ[i]), jv_string(eq + 1));
1140|  }
1141|  return jv_copy(r);
