1144|// Expands call instructions into a calling sequence
1145|static int expand_call_arglist(block* b, jv args, jv *env) {
1146|  int errors = 0;
1147|  block ret = gen_noop();
1148|  for (inst* curr; (curr = block_take(b));) {
1149|    if (opcode_describe(curr->op)->flags & OP_HAS_BINDING) {
1150|      if (!curr->bound_by && curr->op == LOADV && strcmp(curr->symbol, "ENV") == 0) {
1151|        curr->op = LOADK;
1152|        *env = curr->imm.constant = make_env(*env);
1153|      } else if (!curr->bound_by && curr->op == LOADV && jv_object_has(jv_copy(args), jv_string(curr->symbol))) {
1154|        curr->op = LOADK;
1155|        curr->imm.constant = jv_object_get(jv_copy(args), jv_string(curr->symbol));
1156|      } else if (!curr->bound_by) {
1157|        if (curr->symbol[0] == '*' && curr->symbol[1] >= '1' && curr->symbol[1] <= '3' && curr->symbol[2] == '\0')
1158|          locfile_locate(curr->locfile, curr->source, "jq: error: break used outside labeled control structure");
1159|        else if (curr->op == LOADV)
1160|          locfile_locate(curr->locfile, curr->source, "jq: error: $%s is not defined", curr->symbol);
1161|        else
1162|          locfile_locate(curr->locfile, curr->source, "jq: error: %s/%d is not defined", curr->symbol, curr->nactuals);
1163|        errors++;
1164|        // don't process this instruction if it's not well-defined
1165|        ret = BLOCK(ret, inst_block(curr));
1166|        continue;
1167|      }
1168|    }
1169|
1170|    block prelude = gen_noop();
1171|    if (curr->op == CALL_JQ) {
1172|      int actual_args = 0, desired_args = 0;
1173|      // We expand the argument list as a series of instructions
1174|      switch (curr->bound_by->op) {
1175|      default: assert(0 && "Unknown function type"); break;
1176|      case CLOSURE_CREATE:
1177|      case CLOSURE_PARAM: {
1178|        block callargs = gen_noop();
1179|        for (inst* i; (i = block_take(&curr->arglist));) {
1180|          assert(opcode_describe(i->op)->flags & OP_IS_CALL_PSEUDO);
1181|          block b = inst_block(i);
1182|          switch (i->op) {
1183|          default: assert(0 && "Unknown type of parameter"); break;
1184|          case CLOSURE_REF:
1185|            block_append(&callargs, b);
1186|            break;
1187|          case CLOSURE_CREATE:
1188|            block_append(&prelude, b);
1189|            block_append(&callargs, gen_op_bound(CLOSURE_REF, b));
1190|            break;
1191|          }
1192|          actual_args++;
1193|        }
1194|        curr->imm.intval = actual_args;
1195|        curr->arglist = callargs;
1196|
1197|        if (curr->bound_by->op == CLOSURE_CREATE) {
1198|          for (inst* i = curr->bound_by->arglist.first; i; i = i->next) {
1199|            assert(i->op == CLOSURE_PARAM);
1200|            desired_args++;
1201|          }
1202|        }
1203|        break;
1204|      }
1205|
1206|      case CLOSURE_CREATE_C: {
1207|        for (inst* i; (i = block_take(&curr->arglist)); ) {
1208|          assert(i->op == CLOSURE_CREATE); // FIXME
1209|          block body = i->subfn;
1210|          i->subfn = gen_noop();
1211|          inst_free(i);
1212|          // arguments should be pushed in reverse order, prepend them to prelude
1213|          errors += expand_call_arglist(&body, args, env);
1214|          prelude = BLOCK(gen_subexp(body), prelude);
1215|          actual_args++;
1216|        }
1217|        assert(curr->op == CALL_JQ);
1218|        curr->op = CALL_BUILTIN;
1219|        curr->imm.intval = actual_args + 1 /* include the implicit input in arg count */;
1220|        assert(curr->bound_by->op == CLOSURE_CREATE_C);
1221|        desired_args = curr->bound_by->imm.cfunc->nargs - 1;
1222|        assert(!curr->arglist.first);
1223|        break;
1224|      }
1225|      }
1226|
1227|      assert(actual_args == desired_args); // because now handle this above
1228|    }
1229|    ret = BLOCK(ret, prelude, inst_block(curr));
1230|  }
1231|  *b = ret;
1232|  return errors;
1233|}
