1370|int block_compile(block b, struct bytecode** out, struct locfile* lf, jv args) {
1371|  struct bytecode* bc = jv_mem_alloc(sizeof(struct bytecode));
1372|  bc->parent = 0;
1373|  bc->nclosures = 0;
1374|  bc->globals = jv_mem_alloc(sizeof(struct symbol_table));
1375|  int ncfunc = count_cfunctions(b);
1376|  bc->globals->ncfunctions = 0;
1377|  bc->globals->cfunctions = jv_mem_calloc(ncfunc, sizeof(struct cfunction));
1378|  bc->globals->cfunc_names = jv_array();
1379|  bc->debuginfo = jv_object_set(jv_object(), jv_string("name"), jv_null());
1380|  jv env = jv_invalid();
1381|  int nerrors = compile(bc, b, lf, args, &env);
1382|  jv_free(args);
1383|  jv_free(env);
1384|  assert(bc->globals->ncfunctions == ncfunc);
1385|  if (nerrors > 0) {
1386|    bytecode_free(bc);
1387|    *out = 0;
1388|  } else {
1389|    *out = bc;
1390|  }
1391|  return nerrors;
1392|}
