202|static block constant_fold(block a, block b, int op) {
203|  if (!block_is_single(a) || !block_is_const(a) ||
204|      !block_is_single(b) || !block_is_const(b))
205|    return gen_noop();
206|
207|  jv jv_a = block_const(a);
208|  block_free(a);
209|  jv jv_b = block_const(b);
210|  block_free(b);
211|
212|  jv res = jv_invalid();
213|  switch (op) {
214|  case '+': res = binop_plus(jv_a, jv_b); break;
215|  case '-': res = binop_minus(jv_a, jv_b); break;
216|  case '*': res = binop_multiply(jv_a, jv_b); break;
217|  case '/': res = binop_divide(jv_a, jv_b); break;
218|  case '%': res = binop_mod(jv_a, jv_b); break;
219|  case EQ: res = binop_equal(jv_a, jv_b); break;
220|  case NEQ: res = binop_notequal(jv_a, jv_b); break;
221|  case '<': res = binop_less(jv_a, jv_b); break;
222|  case '>': res = binop_greater(jv_a, jv_b); break;
223|  case LESSEQ: res = binop_lesseq(jv_a, jv_b); break;
224|  case GREATEREQ: res = binop_greatereq(jv_a, jv_b); break;
225|  }
226|
227|  if (jv_is_valid(res))
228|    return gen_const(res);
229|
230|  return gen_error(jv_invalid_get_msg(res));
