233|static block gen_binop(block a, block b, int op) {
234|  block folded = constant_fold(a, b, op);
235|  if (!block_is_noop(folded))
236|    return folded;
237|
238|  const char* funcname = 0;
239|  switch (op) {
240|  case '+': funcname = "_plus"; break;
241|  case '-': funcname = "_minus"; break;
242|  case '*': funcname = "_multiply"; break;
243|  case '/': funcname = "_divide"; break;
244|  case '%': funcname = "_mod"; break;
