988|int jq_parse(struct locfile* locations, block* answer) {
989|  struct lexer_param scanner;
990|  YY_BUFFER_STATE buf;
991|  jq_yylex_init_extra(0, &scanner.lexer);
992|  buf = jq_yy_scan_bytes(locations->data, locations->length, scanner.lexer);
993|  int errors = 0;
994|  *answer = gen_noop();
995|  yyparse(answer, &errors, locations, &scanner);
996|  jq_yy_delete_buffer(buf, scanner.lexer);
997|  jq_yylex_destroy(scanner.lexer);
998|  if (errors > 0) {
999|    block_free(*answer);
1000|    *answer = gen_noop();
1001|  }
1002|  return errors;
