56|struct closure {
57|  struct bytecode* bc;  // jq bytecode
58|  stack_ptr env;        // jq stack address of closed frame
59|};
60|
61|// locals for any function called: either a closure or a local variable
62|union frame_entry {
63|  struct closure closure;
64|  jv localvar;
65|};
66|
67|// jq function call frame
68|struct frame {
69|  struct bytecode* bc;      // jq bytecode for callee
70|  stack_ptr env;            // jq stack address of frame to return to
71|  stack_ptr retdata;        // jq stack address to unwind to on RET
72|  uint16_t* retaddr;        // jq bytecode return address
73|  union frame_entry entries[]; // nclosures + nlocals
74|};
75|
76|static int frame_size(struct bytecode* bc) {
77|  return sizeof(struct frame) + sizeof(union frame_entry) * (bc->nclosures + bc->nlocals);
78|}
79|
80|static struct frame* frame_current(struct jq_state* jq) {
81|  struct frame* fp = stack_block(&jq->stk, jq->curr_frame);
82|
83|  stack_ptr next = *stack_block_next(&jq->stk, jq->curr_frame);
84|  if (next) {
85|    struct frame* fpnext = stack_block(&jq->stk, next);
86|    struct bytecode* bc = fpnext->bc;
87|    assert(fp->retaddr >= bc->code && fp->retaddr < bc->code + bc->codelen);
88|  } else {
89|    assert(fp->retaddr == 0);
90|  }
91|  return fp;
92|}
