94|static stack_ptr frame_get_level(struct jq_state* jq, int level) {
95|  stack_ptr fr = jq->curr_frame;
96|  for (int i=0; i<level; i++) {
97|    struct frame* fp = stack_block(&jq->stk, fr);
98|    fr = fp->env;
99|  }
100|  return fr;
101|}
