103|static jv* frame_local_var(struct jq_state* jq, int var, int level) {
104|  struct frame* fr = stack_block(&jq->stk, frame_get_level(jq, level));
105|  assert(var >= 0);
106|  assert(var < fr->bc->nlocals);
107|  return &fr->entries[fr->bc->nclosures + var].localvar;
108|}
