110|static struct closure make_closure(struct jq_state* jq, uint16_t* pc) {
111|  uint16_t level = *pc++;
112|  uint16_t idx = *pc++;
113|  stack_ptr fridx = frame_get_level(jq, level);
114|  struct frame* fr = stack_block(&jq->stk, fridx);
115|  if (idx & ARG_NEWCLOSURE) {
116|    // A new closure closing the frame identified by level, and with
117|    // the bytecode body of the idx'th subfunction of that frame
118|    int subfn_idx = idx & ~ARG_NEWCLOSURE;
119|    assert(subfn_idx < fr->bc->nsubfunctions);
120|    struct closure cl = {fr->bc->subfunctions[subfn_idx],
121|                         fridx};
122|    return cl;
123|  } else {
124|    // A reference to a closure from the frame identified by level; copy
125|    // it as-is
126|    int closure = idx;
127|    assert(closure >= 0);
128|    assert(closure < fr->bc->nclosures);
129|    return fr->entries[closure].closure;
130|  }
131|}
