133|static struct frame* frame_push(struct jq_state* jq, struct closure callee,
134|                                uint16_t* argdef, int nargs) {
135|  stack_ptr new_frame_idx = stack_push_block(&jq->stk, jq->curr_frame, frame_size(callee.bc));
136|  struct frame* new_frame = stack_block(&jq->stk, new_frame_idx);
137|  new_frame->bc = callee.bc;
138|  new_frame->env = callee.env;
139|  assert(nargs == new_frame->bc->nclosures);
140|  union frame_entry* entries = new_frame->entries;
141|  for (int i=0; i<nargs; i++) {
142|    entries->closure = make_closure(jq, argdef + i * 2);
143|    entries++;
144|  }
145|  for (int i=0; i<callee.bc->nlocals; i++) {
146|    entries->localvar = jv_invalid();
147|    entries++;
148|  }
149|  jq->curr_frame = new_frame_idx;
150|  return new_frame;
151|}
