153|static void frame_pop(struct jq_state* jq) {
154|  assert(jq->curr_frame);
155|  struct frame* fp = frame_current(jq);
156|  if (stack_pop_will_free(&jq->stk, jq->curr_frame)) {
157|    int nlocals = fp->bc->nlocals;
158|    for (int i=0; i<nlocals; i++) {
159|      jv_free(*frame_local_var(jq, i, 0));
160|    }
161|  }
162|  jq->curr_frame = stack_pop_block(&jq->stk, jq->curr_frame, frame_size(fp->bc));
163|}
