273|uint16_t* stack_restore(jq_state *jq){
274|  while (!stack_pop_will_free(&jq->stk, jq->fork_top)) {
275|    if (stack_pop_will_free(&jq->stk, jq->stk_top)) {
276|      jv_free(stack_pop(jq));
277|    } else if (stack_pop_will_free(&jq->stk, jq->curr_frame)) {
278|      frame_pop(jq);
279|    } else {
280|      assert(0);
281|    }
282|  }
283|
284|  if (jq->fork_top == 0) {
285|    return 0;
286|  }
287|
288|  struct forkpoint* fork = stack_block(&jq->stk, jq->fork_top);
289|  uint16_t* retaddr = fork->return_address;
290|  jq->stk_top = fork->saved_data_stack;
291|  jq->curr_frame = fork->saved_curr_frame;
292|  int path_len = fork->path_len;
293|  if (jv_get_kind(jq->path) == JV_KIND_ARRAY) {
294|    assert(path_len >= 0);
295|    jq->path = jv_array_slice(jq->path, 0, path_len);
296|  } else {
297|    fork->path_len = 0;
298|  }
299|  jv_free(jq->value_at_path);
300|  jq->value_at_path = fork->value_at_path;
301|  jq->subexp_nest = fork->subexp_nest;
302|  jq->fork_top = stack_pop_block(&jq->stk, jq->fork_top, sizeof(struct forkpoint));
303|  return retaddr;
304|}
