1005|jv jq_format_error(jv msg) {
1006|  if (jv_get_kind(msg) == JV_KIND_NULL ||
1007|      (jv_get_kind(msg) == JV_KIND_INVALID && !jv_invalid_has_msg(jv_copy(msg)))) {
1008|    jv_free(msg);
1009|    fprintf(stderr, "jq: error: out of memory\n");
1010|    return jv_null();
1011|  }
1012|
1013|  if (jv_get_kind(msg) == JV_KIND_STRING)
1014|    return msg;                         // expected to already be formatted
1015|
1016|  if (jv_get_kind(msg) == JV_KIND_INVALID)
1017|    msg = jv_invalid_get_msg(msg);
1018|
1019|  if (jv_get_kind(msg) == JV_KIND_NULL)
1020|    return jq_format_error(msg);        // ENOMEM
1021|
1022|  // Invalid with msg; prefix with "jq: error: "
1023|
1024|  if (jv_get_kind(msg) != JV_KIND_INVALID) {
1025|    if (jv_get_kind(msg) == JV_KIND_STRING)
1026|      return jv_string_fmt("jq: error: %s", jv_string_value(msg));
1027|
1028|    msg = jv_dump_string(msg, JV_PRINT_INVALID);
1029|    if (jv_get_kind(msg) == JV_KIND_STRING)
1030|      return jv_string_fmt("jq: error: %s", jv_string_value(msg));
1031|    return jq_format_error(jv_null());  // ENOMEM
1032|  }
1033|
1034|  // An invalid inside an invalid!
1035|  return jq_format_error(jv_invalid_get_msg(msg));
1036|}
