1183|static struct bytecode *optimize_code(struct bytecode *bc) {
1184|  uint16_t *pc = bc->code;
1185|  // FIXME: Don't mutate bc->code...
1186|  while (pc < bc->code + bc->codelen) {
1187|    switch (*pc) {
1188|    case CALL_JQ:
1189|      *pc = tail_call_analyze(pc);
1190|      break;
1191|
1192|    // Other bytecode optimizations here.  A peephole optimizer would
1193|    // fit right in.
1194|    default: break;
1195|    }
1196|    pc += bytecode_operation_length(pc);
1197|  }
1198|  return bc;
1199|}
