1201|static struct bytecode *optimize(struct bytecode *bc) {
1202|  for (int i=0; i<bc->nsubfunctions; i++) {
1203|    bc->subfunctions[i] = optimize(bc->subfunctions[i]);
1204|  }
1205|  return optimize_code(bc);
