136|static jv find_lib(jq_state *jq, jv rel_path, jv search, const char *suffix, jv jq_origin, jv lib_origin) {
137|  if (!jv_is_valid(rel_path)) {
138|    jv_free(search);
139|    jv_free(jq_origin);
140|    jv_free(lib_origin);
141|    return rel_path;
142|  }
143|  if (jv_get_kind(rel_path) != JV_KIND_STRING) {
144|    jv_free(rel_path);
145|    jv_free(search);
146|    jv_free(jq_origin);
147|    jv_free(lib_origin);
148|    return jv_invalid_with_msg(jv_string_fmt("Module path must be a string"));
149|  }
150|  if (jv_get_kind(search) != JV_KIND_ARRAY) {
151|    jv_free(rel_path);
152|    jv_free(search);
153|    jv_free(jq_origin);
154|    jv_free(lib_origin);
155|    return jv_invalid_with_msg(jv_string_fmt("Module search path must be an array"));
156|  }
157|
158|  struct stat st;
159|  int ret;
160|
161|  // Ideally we should cache this somewhere
162|  search = build_lib_search_chain(jq, search, jq_origin, lib_origin);
163|  jv err = jv_array_get(jv_copy(search), 1);
164|  search = jv_array_get(search, 0);
165|
166|  jv bname = jv_basename(jv_copy(rel_path));
167|
168|  jv_array_foreach(search, i, spath) {
169|    if (jv_get_kind(spath) == JV_KIND_NULL) {
170|      jv_free(spath);
171|      break;
172|    }
173|    if (jv_get_kind(spath) != JV_KIND_STRING ||
174|        strcmp(jv_string_value(spath), "") == 0) {
175|      jv_free(spath);
176|      continue; /* XXX report non-strings in search path?? */
177|    }
178|    // Try ${search_dir}/${rel_path}.jq
179|    jv testpath = jq_realpath(jv_string_fmt("%s/%s%s",
180|                                            jv_string_value(spath),
181|                                            jv_string_value(rel_path),
182|                                            suffix));
183|    ret = stat(jv_string_value(testpath),&st);
184|    if (ret == -1 && errno == ENOENT) {
185|      jv_free(testpath);
186|      // Try ${search_dir}/$(dirname ${rel_path})/jq/main.jq
187|      testpath = jq_realpath(jv_string_fmt("%s/%s/%s%s",
188|                                           jv_string_value(spath),
189|                                           jv_string_value(rel_path),
190|                                           "jq/main",
191|                                           suffix));
192|      ret = stat(jv_string_value(testpath),&st);
193|    }
194|    if (ret == -1 && errno == ENOENT) {
195|      jv_free(testpath);
196|      // Try ${search_dir}/${rel_path}/$(basename ${rel_path}).jq
197|      testpath = jq_realpath(jv_string_fmt("%s/%s/%s%s",
198|                                           jv_string_value(spath),
199|                                           jv_string_value(rel_path),
200|                                           jv_string_value(bname),
201|                                           suffix));
202|      ret = stat(jv_string_value(testpath),&st);
203|    }
204|    if (ret == 0) {
205|      jv_free(err);
206|      jv_free(rel_path);
207|      jv_free(search);
208|      jv_free(bname);
209|      jv_free(spath);
210|      return testpath;
211|    }
212|    jv_free(testpath);
213|    jv_free(spath);
214|  }
215|  jv output;
216|  if (!jv_is_valid(err)) {
217|    err = jv_invalid_get_msg(err);
