176|static int process(jq_state *jq, jv value, int flags, int dumpopts, int options) {
177|  int ret = JQ_OK_NO_OUTPUT; // No valid results && -e -> exit(4)
178|  jq_start(jq, value, flags);
179|  jv result;
180|  while (jv_is_valid(result = jq_next(jq))) {
181|    if ((options & RAW_OUTPUT) && jv_get_kind(result) == JV_KIND_STRING) {
182|      if (options & ASCII_OUTPUT) {
183|        jv_dumpf(jv_copy(result), stdout, JV_PRINT_ASCII);
184|      } else if ((options & RAW_OUTPUT0) && strlen(jv_string_value(result)) != (unsigned long)jv_string_length_bytes(jv_copy(result))) {
185|        jv_free(result);
186|        result = jv_invalid_with_msg(jv_string(
187|              "Cannot dump a string containing NUL with --raw-output0 option"));
188|        break;
189|      } else {
190|        priv_fwrite(jv_string_value(result), jv_string_length_bytes(jv_copy(result)),
191|            stdout, dumpopts & JV_PRINT_ISATTY);
192|      }
193|      ret = JQ_OK;
194|      jv_free(result);
195|    } else {
196|      if (jv_get_kind(result) == JV_KIND_FALSE || jv_get_kind(result) == JV_KIND_NULL)
197|        ret = JQ_OK_NULL_KIND;
198|      else
199|        ret = JQ_OK;
200|      if (options & SEQ)
201|        priv_fwrite("\036", 1, stdout, dumpopts & JV_PRINT_ISATTY);
202|      jv_dump(result, dumpopts);
203|    }
204|    if (!(options & RAW_NO_LF))
205|      priv_fwrite("\n", 1, stdout, dumpopts & JV_PRINT_ISATTY);
206|    if (options & RAW_OUTPUT0)
207|      priv_fwrite("\0", 1, stdout, dumpopts & JV_PRINT_ISATTY);
208|    if (options & UNBUFFERED_OUTPUT)
209|      fflush(stdout);
210|  }
211|  if (jq_halted(jq)) {
212|    // jq program invoked `halt` or `halt_error`
213|    jv exit_code = jq_get_exit_code(jq);
214|    if (!jv_is_valid(exit_code))
215|      ret = JQ_OK;
216|    else if (jv_get_kind(exit_code) == JV_KIND_NUMBER)
217|      ret = jv_number_value(exit_code);
218|    else
219|      ret = JQ_ERROR_UNKNOWN;
220|    jv_free(exit_code);
221|    jv error_message = jq_get_error_message(jq);
222|    if (jv_get_kind(error_message) == JV_KIND_STRING) {
223|      // No prefix should be added to the output of `halt_error`.
224|      priv_fwrite(jv_string_value(error_message), jv_string_length_bytes(jv_copy(error_message)),
225|          stderr, dumpopts & JV_PRINT_ISATTY);
226|    } else if (jv_get_kind(error_message) == JV_KIND_NULL) {
227|      // Halt with no output
228|    } else if (jv_is_valid(error_message)) {
229|      error_message = jv_dump_string(error_message, 0);
230|      fprintf(stderr, "%s\n", jv_string_value(error_message));
231|    } // else no message on stderr; use --debug-trace to see a message
232|    fflush(stderr);
233|    jv_free(error_message);
234|  } else if (jv_invalid_has_msg(jv_copy(result))) {
235|    // Uncaught jq exception
236|    jv msg = jv_invalid_get_msg(jv_copy(result));
237|    jv input_pos = jq_util_input_get_position(jq);
238|    if (jv_get_kind(msg) == JV_KIND_STRING) {
239|      fprintf(stderr, "jq: error (at %s): %s\n",
240|              jv_string_value(input_pos), jv_string_value(msg));
241|    } else {
242|      msg = jv_dump_string(msg, 0);
243|      fprintf(stderr, "jq: error (at %s) (not a string): %s\n",
244|              jv_string_value(input_pos), jv_string_value(msg));
245|    }
246|    ret = JQ_ERROR_UNKNOWN;
247|    jv_free(input_pos);
248|    jv_free(msg);
249|  }
250|  jv_free(result);
251|  return ret;
252|}
